        m = re.fullmatch(r"(\*|(\d+)(?:-(\d+))?)(?:/(\d+))?", part)
        if not m:
            raise CronError(f"bad field {text!r}")
        step = int(m.group(4)) if m.group(4) else 1
        if step < 1:
            raise CronError(f"step must be at least 1 in {text!r}")
        if m.group(1) == "*":
            a, b = lo, hi
        else:
